source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find each 3-by-3 ring around a 2 center.
    objects = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if all(grid[r + dr][c + dc] == (2 if dr == dc == 0 else 3)
                   for dr in (-1, 0, 1) for dc in (-1, 0, 1)):
                row_score = sum(x == 2 for x in grid[r])
                col_score = sum(grid[i][c] == 2 for i in range(h))
                orientation = "horizontal" if row_score > col_score else "vertical"
                objects.append((r, c, orientation))

    for r, c, orientation in objects:
        if orientation == "vertical":
            bars = [j for j in range(w) if sum(grid[i][j] == 2 for i in range(h)) > h // 2]
            # Extend the center across the row, leaving existing 2s and 3s intact.
            for j in range(w):
                if out[r][j] == 0:
                    out[r][j] = 1
            # Copy the ring to the other vertical separator lines.
            for j in bars:
                if j == c:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == dc == 0:
                            continue
                        rr, cc = r + dr, j + dc
                        if 0 <= rr < h and 0 <= cc < w and out[rr][cc] != 3:
                            out[rr][cc] = 1
        else:
            bars = [i for i in range(h) if sum(x == 2 for x in grid[i]) > w // 2]
            # Extend the center across the column, leaving existing 2s and 3s intact.
            for i in range(h):
                if out[i][c] == 0:
                    out[i][c] = 1
            # Copy the ring to the other horizontal separator lines.
            for i in bars:
                if i == r:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == dc == 0:
                            continue
                        rr, cc = i + dr, c + dc
                        if 0 <= rr < h and 0 <= cc < w and out[rr][cc] != 3:
                            out[rr][cc] = 1
    return out
'''
